Definition prep_exit_post (sp gp tp : word) (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi ff fp : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom bsegs)
    /\ munch [(ff, ff + 8); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
