Lemma prep_exit : forall (m : mem) (sp : word) (spa lo shi ff fp b n0 res cur beg : Z) (LF : list fframe) (gap : list cell)
    (j0 j24 j96 j120 j176 h40 h112 : list byte) (sh16 : list cell) (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
    (rax gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
  rw_cells bsegs m spa (prep_locals3 b n0 ff res cur j0 j24 j96 j120 j176) ->
  rw_cells bsegs m (spa + 184) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184) ->
  rw_cells bsegs m (bv_unsigned sp + -104) (prep_saves s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
  rw_cells bsegs m ff (prep_ff2 ff spa fp beg h40 h112) ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) sh16 -> Z.of_nat (cells_size sh16) = 16 -> sh16 = prep_sh2 ->
  rw_cells bsegs m fp [C1 (b8 1)] ->
  bv_unsigned sp + -304 <= spa <= bv_unsigned sp + -288 ->
  stk bsegs m lo spa -> lo + 304 <= bv_unsigned sp -> aceil <= lo -> mem_inv bsegs m ->
  as_RFS H ((1, ff, fp) :: LF) m -> fresh_frame H LF 1 ff fp -> ACONST m -> stack0 m lo shi ->
  bv_unsigned rav mod 2 = 0 -> 0 <= n0 < 2^62 ->
  evt bsegs (prep_exit_post sp gp tp s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav F fc LF lo shi ff fp m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 n0) (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 res) (Z_to_bv 64 (b + 8)) (Z_to_bv 64 2147450880) (Z_to_bv 64 ff)
             (Z_to_bv 64 n0) (Z_to_bv 64 ff) s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_PREP_ASSERT) fc None m (seg_rom bsegs)).
