Section TAILCTX.
  Hypothesis MEMSET : asan_memset_stmt.
  Variables (sp : word) (spa lo shi : Z) (res b : Z) (es : list mbe) (insz n x ff fp : Z) (LF0 : list fframe).
  Variables (LB : list block) (s_ : as_St H) (m0 : mem).
  Hypothesis SPAR : bv_unsigned sp + -304 <= spa <= bv_unsigned sp + -288.
  Hypothesis SPA16 : spa mod 16 = 0.
  Hypothesis LO : lo + 304 + MB_SR_STACK <= bv_unsigned sp.
  Hypothesis CEIL : aceil <= lo.
  Hypothesis OK : mb_ok es insz.
  Hypothesis N1 : 1 <= n.
  Hypothesis NB : insz + n <= 2^26.
  Hypothesis FF : fresh_frame H LF0 1 ff fp.
  Hypothesis SHI : bv_unsigned sp <= shi.
  Hypothesis RAP : aapp res 40.
  Hypothesis RAL : res mod 8 = 0.
  Hypothesis ROFF : mb_off b (mb_put_es es insz n x) res 40.
  Hypothesis DRF : res + 40 <= ff \/ ff + 128 <= res.
  Hypothesis RH : as_RHEAP H s_ LB m0.
  Hypothesis AOR : aobj LB LF0 res 40.
  Hypothesis DBF : b + 64 <= ff \/ ff + 128 <= b.
  Hypothesis DRP : res + 40 <= fp \/ fp + 1 <= res.
  Hypothesis DBP : b + 64 <= fp \/ fp + 1 <= b.
