  (* [comment removed for export] *)
  Definition prep_tailW : list (Z * Z) :=
    [(lo, spa + 184); (res, res + 40); (ff, ff + 8); (ff + 32, ff + 40); (Z.shiftr ff 3 + 2147450880, Z.shiftr ff 3 + 2147450880 + 16); (fp, fp + 1)]%Z.

  Definition prep_tail_post (gp tp : word) (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word) (F : bvmap 5 word) (fc : bv 32)
      (m : mem) : machine_state -> Prop :=
    fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
      ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v t3 t4 t5 t6)
               F (ret_pc rav) fc None m' (seg_rom bsegs)
      /\ munch prep_tailW m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
      /\ stk bsegs m' lo (bv_unsigned sp)
      /\ rw_cells bsegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
      /\ AMBmid m' b es insz n x
      /\ as_RFS H LF0 m' /\ ACONST m' /\ stack0 m' lo shi.

  Lemma prep_tail : forall (m : mem) (gap : list cell) (j0 j24 j96 j120 h32 h112 rj : list byte)
      (s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav : word)
      (rax gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s8x s10x s11x t3 t4 t5 t6 : word) (F : bvmap 5 word) fc,
    AMBmid m b es insz n x ->
    rw_cells bsegs m res [CB 40 rj] -> accessible m res 40 -> shvis m res (res + 40) ->
    rw_cells bsegs m spa (prep_locals1 b n ff j0 j24 j96 j120) ->
    rw_cells bsegs m (spa + 184) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -104 - (spa + 184) ->
    rw_cells bsegs m (bv_unsigned sp + -104) (prep_saves s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav) ->
    rw_cells bsegs m ff (prep_ff1 ff spa fp h32 h112) ->
    rw_cells bsegs m (Z.shiftr ff 3 + 2147450880) prep_sh1 ->
    rw_cells bsegs m fp [C1 (b8 1)] ->
    stk bsegs m lo spa -> mem_inv bsegs m -> as_RFS H ((1, ff, fp) :: LF0) m -> ACONST m -> stack0 m lo shi ->
    bv_unsigned rav mod 2 = 0 ->
    evt bsegs (prep_tail_post gp tp s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v rav F fc m)
      (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
               s2x (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 res) (Z_to_bv 64 b) (Z_to_bv 64 2147450880) (Z_to_bv 64 ff)
               s8x (Z_to_bv 64 ff) s10x s11x t3 t4 t5 t6)
          F (Z_to_bv 64 P_A_PREP_TAIL) fc None m (seg_rom bsegs)).
